function h82_p($text,$class='') { return '<!-- wp:paragraph '.($class?wp_json_encode(['className'=>$class]):'').' --><p'.($class?' class="'.esc_attr($class).'"':'').'>'.$text.'</p><!-- /wp:paragraph -->'; }
function h82_h($text,$id='',$level=2) { return '<!-- wp:heading '.wp_json_encode(['level'=>$level,'anchor'=>$id]).' --><h'.$level.' class="wp-block-heading"'.($id?' id="'.esc_attr($id).'"':'').'>'.$text.'</h'.$level.'><!-- /wp:heading -->'; }
function h82_short($text) { return '<!-- wp:shortcode -->'.$text.'<!-- /wp:shortcode -->'; }
function h82_group($class,$content) { return '<!-- wp:group '.wp_json_encode(['className'=>$class,'layout'=>['type'=>'default']]).' --><div class="wp-block-group '.$class.'">'.$content.'</div><!-- /wp:group -->'; }
function h82_page($title,$lead,$sections,$form=false) {
    $body='';foreach($sections as $heading=>$paragraphs) { $body.=h82_h($heading,sanitize_title($heading));foreach($paragraphs as $p) { $body.=h82_p($p); } }
    return h82_group('cb-container cc-legal',h82_group('cc-legal-heading',h82_h($title,'',1).h82_p($lead,'cc-legal-lead').h82_p('<strong>DEMO · Contenido de muestra.</strong> Pendiente de datos del titular y revisión jurídica del comercio. Esta tienda local no recibe operaciones reales.','cc-demo')).h82_group('cc-legal-layout',h82_short('[commerce_legal_navigation]').h82_group('cc-legal-copy',($form?h82_short('[commerce_legal_form]'):'').$body.h82_short('[commerce_legal_identity]'))));
}
$pages=[];
foreach(['privacy'=>['privacy-policy','Política de privacidad'],'terms'=>['terminos','Términos y condiciones'],'shipping'=>['envios','Envíos'],'returns'=>['cambios-y-devoluciones','Cambios y devoluciones'],'withdrawal'=>['boton-de-arrepentimiento','Derecho de arrepentimiento']] as $key=>$pair) {
    $existing=get_page_by_path($pair[0]);
    if($existing && !($key==='privacy' && $existing->ID===3 && $existing->post_status==='draft' && str_contains($existing->post_content,'Who we are'))) { WP_CLI::error('Unexpected existing page. Review before reuse: '.$pair[0]); }
    $id=$existing ? $existing->ID : wp_insert_post(['post_type'=>'page','post_status'=>'draft','post_name'=>$pair[0],'post_title'=>$pair[1]],true);
    if(is_wp_error($id)) { WP_CLI::error($id->get_error_message()); }$pages[$key]=(int)$id;
}
